definitions._Ring:
class _Ring:
    def __init__(self):
        self.indices = array('i')
        self.tickers = []
        self.values = {field: array('d') for field in _FIELDS}

    def append(self, row, index):
        if self.indices and index <= self.indices[-1]:
            raise ValueError('FORMATION_PRICE_ORDER_CHANGED')
        if row.close_signal is None:
            raise ValueError('FORMATION_PUBLISHED_SIGNAL_MISSING')
        self.indices.append(index)
        self.tickers.append(row.ticker)
        for field in _FIELDS:
            value = getattr(row, field)
            self.values[field].append(float('nan') if value is None else value)

    def expire(self, lower):
        count = 0
        while count < len(self.indices) and self.indices[count] < lower:
            count += 1
        if count:
            del self.indices[:count]
            del self.tickers[:count]
            for values in self.values.values():
                del values[:count]

    def history(self, sid, axis, first, last):
        return tuple(CanonicalBar(security_id=sid, session=axis[index],
            ticker=self.tickers[offset], **{field: _value(values[offset])
            for field, values in self.values.items()})
            for offset, index in enumerate(self.indices) if first <= index < last)

definitions._defensive:
def _defensive(row: CanonicalBenchmark) -> DefensiveBar:
    return DefensiveBar(
        session=row.session.isoformat(), security_id="SENTINEL:BIL", ticker="BIL",
        open_signal=row.bil_open_signal, close_signal=row.bil_close_signal,
        close_adjusted=row.bil_close_adjusted,
        close_unadjusted=row.bil_close_unadjusted)

definitions.Signal:
class Signal(Contract):
    model_config = ConfigDict(extra='forbid', frozen=True, allow_inf_nan=False)
    security_id: str
    ticker: str
    issuer_id: str
    closes: tuple[float | None, ...] = Field(max_length=127)
    raw_close: float | None
    eligible: bool
    eligibility_reason: str
    certified_signals: tuple[float, float, float, float] | None

    @classmethod
    def from_feature(cls, bar):
        value = asdict(bar)
        value['closes'] = value['closes'][-1:]
        return cls.model_validate(value)

    def bar(self, multiplier=1.):
        return SecurityBar(self.security_id, self.ticker, self.issuer_id,
            tuple(None if c is None else c*multiplier for c in self.closes),
            self.raw_close, self.eligible, self.eligibility_reason, self.certified_signals)

definitions.WindowFeatures:
class WindowFeatures(Contract):
    schema_id: Literal['sentinel.current-window-features/1'] = Field(
        default='sentinel.current-window-features/1', alias='schema')
    snapshot_sha256: Digest
    prior_state_sha256: Digest
    publication_version: int = Field(gt=0)
    sessions: tuple[str, ...] = Field(min_length=300, max_length=300)
    signals: tuple[Signal, ...]
    histories: dict[str, tuple[CanonicalBar, ...]]

    @property
    def sha256(self):
        return digest(self.model_dump(mode='json', by_alias=True))

definitions.load:
def load(conn, *, prior, refs, publication, session=None):
    """One identity-ordered stream; retain 127 features plus live 260-row tails."""
    from sentinel.feed.rolling_contract import CurrentFormationWindow
    session = session or publication.window_end
    axis = calendar.previous_sessions(session, 300)
    available = list(map(str, refs.manifest.window.sessions))
    if (axis != available and not (isinstance(refs.manifest.window, CurrentFormationWindow)
                                   and set(axis).issubset(available))):
        raise ValueError('CURRENT_WINDOW_AXIS_REQUIRED')
    indices = {day:i for i, day in enumerate(axis)}
    live = protected(prior)
    signals, histories = [], {sid:[] for sid in live}
    meta, _ = refs.current_metadata(session=session)
    columns = rolling_store.BAR_COLUMNS
    query = (f"SELECT {','.join(columns)} FROM sentinel_snapshot_bars WHERE candidate_id=%s "
             'AND session BETWEEN %s AND %s '
             'ORDER BY security_id COLLATE "C",session')
    with store.streaming_cursor(conn, query, (refs.candidate_id, axis[0], axis[-1])) as cursor:
        rows = (CanonicalBar.model_validate(dict(zip(columns, row))) for row in cursor)
        for sid, group in groupby(rows, key=lambda row: row.security_id):
            series = None
            for row in group:
                day = str(row.session)
                if day not in indices or refs.resolver.resolve(row.ticker, day) != sid or sid not in meta:
                    raise ValueError('CURRENT_WINDOW_IDENTITY_OR_AXIS_CHANGED')
                if series is None:
                    series = SecuritySeries(sid, row.ticker, f'SID:{sid}')
                series.append(_vendor(row), indices[day], published_signal=True)
                if sid in live and axis[-261] <= day < axis[-1]:
                    histories[sid].append(row)
            if series is not None and series.sessions[-1] == axis[-1]:
                signals.append(Signal.from_feature(feature(
                    series, meta[sid], index=299, session=axis[-1])))
    return WindowFeatures(snapshot_sha256=refs.manifest.snapshot_id,
        prior_state_sha256=prior.state_hash, publication_version=publication.version,
        sessions=tuple(axis), signals=tuple(signals), histories=histories)

definitions.benchmarks:
def benchmarks(window, rows):
    by_key = {}
    for row in rows:
        key = (str(row["date"]), str(row["ticker"]))
        if key in by_key or key[1] not in {"SPY", "BIL"}:
            raise ValueError("duplicate or unexpected benchmark identity")
        by_key[key] = row
    expected = {(str(day), ticker) for day in window.sessions for ticker in ("SPY", "BIL")}
    if set(by_key) != expected:
        raise ValueError("SPY/BIL must cover every session exactly")
    for day in window.sessions:
        spy, bil = by_key[(str(day), "SPY")], by_key[(str(day), "BIL")]
        # Same mandatory BIL fields as the existing dedicated defensive writer.
        yield CanonicalBenchmark(
            session=day, spy_total_return=float(spy[_SFP_TOTAL_RETURN_COLUMN]),
            bil_open_signal=float(bil["open"]), bil_close_signal=float(bil["close"]),
            bil_close_adjusted=float(bil[_SFP_TOTAL_RETURN_COLUMN]),
            bil_close_unadjusted=float(bil["closeunadj"]))

definitions._finite_decimal:
def _finite_decimal(value: Any, *, where: str) -> Decimal:
    if isinstance(value, bool):
        raise ShadowObservationRefused(f"{where} is not a finite decimal")
    try:
        result = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ShadowObservationRefused(
            f"{where} is not a finite decimal") from exc
    if not result.is_finite():
        raise ShadowObservationRefused(f"{where} is not a finite decimal")
    return result

definitions._optional_decimal_text:
def _optional_decimal_text(
        value: Any, *, where: str, positive: bool = False,
        nonnegative: bool = False) -> str | None:
    if value is None:
        return None
    result = _finite_decimal(value, where=where)
    if ((positive and result <= 0)
            or (nonnegative and result < 0)):
        raise ShadowObservationRefused(
            f"{where} is outside its economic price/quantity domain")
    return _decimal_text(result)

definitions._positive_decimal:
def _positive_decimal(value: Any, *, where: str) -> Decimal:
    try:
        result = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ShadowObservationRefused(f"{where} is not a decimal") from exc
    if not result.is_finite() or result <= 0:
        raise ShadowObservationRefused(
            f"{where} must be finite and positive")
    return result

definitions._signal_price_identity:
def _signal_price_identity(bar, anchor, *, warmup: bool = False) -> dict | None:
    """Bind a signal observation to its same-security source predecessor.

    Warmup supplies the first positive observation of the security's window.
    A genuinely new series has no predecessor and establishes its own basis.
    The canonical feed retains the owned absolute level for mixed precision.
    """
    if bar.signal_close is None:
        return None
    if anchor is None:
        return {"anchor": None,
                "ratio": _exact_price_ratio(bar.signal_close, bar.signal_close)}
    if (anchor.security_id != bar.security_id
            or anchor.session > bar.session
            or (not warmup and anchor.session == bar.session)):
        raise ShadowObservationRefused("signal basis anchor identity is invalid")
    return {
        "anchor": {
            "security_id": str(anchor.security_id), "ticker": str(anchor.ticker),
            "session": str(anchor.session),
            "raw_close": _optional_decimal_text(
                anchor.raw_close, where="signal basis raw close", positive=True),
        },
        "ratio": _exact_price_ratio(bar.signal_close, anchor.signal_close),
    }

definitions._canonical_json:
def _canonical_json(value) -> str:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=True,
        allow_nan=False)

definitions._decimal_text:
def _decimal_text(value, *, where: str, positive: bool = False,
                  nonnegative: bool = False) -> str | None:
    if value is None:
        return None
    if isinstance(value, bool):
        raise ShadowRuntimeRefused(f"{where} is not a finite decimal")
    try:
        number = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ShadowRuntimeRefused(
            f"{where} is not a finite decimal") from exc
    if (not number.is_finite()
            or (positive and number <= 0)
            or (nonnegative and number < 0)):
        raise ShadowRuntimeRefused(
            f"{where} is outside its economic domain")
    return format(number.normalize(), "f")

definitions._starting_cash:
def _starting_cash(value: Decimal | str | int | float) -> Decimal:
    if isinstance(value, bool):
        raise ShadowRuntimeRefused(
            "shadow starting cash must be an explicit positive decimal")
    try:
        amount = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ShadowRuntimeRefused(
            "shadow starting cash must be an explicit positive decimal") from exc
    if not amount.is_finite() or amount <= 0:
        raise ShadowRuntimeRefused(
            "shadow starting cash must be an explicit positive decimal")
    as_float = float(amount)
    if not math.isfinite(as_float) or Decimal(str(as_float)) != amount:
        raise ShadowRuntimeRefused(
            "shadow starting cash is not exactly representable by Wealth Core")
    return amount

definitions._stream_sha256:
def _stream_sha256(values) -> str:
    """Length-frame canonical rows so a large warm-up never becomes one blob."""
    digest = hashlib.sha256()
    for value in values:
        encoded = _canonical_json(value).encode("ascii")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
    return digest.hexdigest()

definitions._warmup_input_identity:
def _warmup_input_identity(
        window, sessions: list[str], *, prospective_witness: bool,
        expected_sessions: int = WARMUP_SESSIONS) -> dict:
    """Compact exact economic identity of every input that creates the seed."""
    ordered = [str(session) for session in sessions]
    if (expected_sessions not in (252, 299) or len(ordered) != expected_sessions
            or window.sessions != ordered
            or any(left >= right for left, right in zip(ordered, ordered[1:]))):
        raise ShadowRuntimeRefused(
            "shadow warm-up identity requires the selected feature-session axis")

    signal_anchors = {}
    if hasattr(window, "median5_spy_closes"):
        spy = window.median5_spy_closes
        if not isinstance(spy, Mapping) or set(spy) != set(ordered):
            raise ShadowRuntimeRefused("shadow warm-up requires the exact dated SPY history")
        if any(_decimal_text(spy[session], where=f"warm-up SPY close {session}",
                             positive=True) is None for session in ordered):
            raise ShadowRuntimeRefused("shadow warm-up requires positive SPY closes")
        for session in ordered:
            for bar in window.bars_by_session.get(session, ()):
                if bar.signal_close is not None:
                    signal_anchors.setdefault(bar.security_id, bar)

    def economic_bar(bar, *, session: str, index: int) -> dict:
        raw_close = _decimal_text(
            bar.raw_close, where=f"warm-up raw close {session}/{index}",
            positive=True)
        raw_open = _decimal_text(
            bar.raw_open, where=f"warm-up raw open {session}/{index}",
            positive=True)
        volume = _decimal_text(
            bar.volume, where=f"warm-up volume {session}/{index}",
            nonnegative=True)
        liquidity = None
        if raw_close is not None and volume is not None:
            liquidity = format(
                (Decimal(raw_close) * Decimal(volume)).normalize(), "f")
        return {
            **({"signal_close": _signal_price_identity(
                    bar, signal_anchors.get(bar.security_id), warmup=True),
                "raw_compatible_volume": volume}
               if hasattr(window, "median5_spy_closes") else {}),
            "security_id": str(bar.security_id),
            "ticker": str(bar.ticker),
            "raw_close": raw_close,
            "raw_open": raw_open,
            # Stored volume is already in raw-compatible shares.  This product
            # is exactly SEP.close * source volume, so a later split's inverse
            # close/volume rescale cannot change the committed liquidity.
            "raw_dollar_liquidity": liquidity,
            "split_ratio": _decimal_text(
                bar.split_ratio,
                where=f"warm-up split ratio {session}/{index}",
                positive=True),
            "dividend_per_share": _decimal_text(
                bar.dividend_per_share,
                where=f"warm-up dividend {session}/{index}",
                nonnegative=True),
            "tradeable": bool(bar.tradeable),
            "unresolved_corporate_action": bool(
                bar.unresolved_corporate_action),
        }

    def bar_rows():
        for session in ordered:
            bars = sorted(
                window.bars_by_session.get(session, ()),
                key=lambda item: (str(item.security_id), str(item.ticker)))
            yield {
                "session": session,
                "bars": [economic_bar(bar, session=session, index=index)
                         for index, bar in enumerate(bars)],
            }

    if prospective_witness:
        metadata_mode = "PROSPECTIVE_STATIC_FEATURE_METADATA"
        metadata_values = [{
            "security_id": str(security_id),
            "metadata": asdict(meta),
        } for security_id, meta in sorted(window.meta.items())]
    else:
        timeline = window.metadata_timeline
        if timeline is None or list(timeline.sessions) != ordered:
            raise ShadowRuntimeRefused(
                "causal shadow warm-up lacks its exact metadata timeline")
        metadata_mode = "CAUSAL_METADATA_TIMELINE"
        metadata_values = ({
            "session": session,
            "rows": [timeline.canonical_row(session, bar.security_id)
                     for bar in sorted(
                         window.bars_by_session.get(session, ()),
                         key=lambda item: (
                             str(item.security_id), str(item.ticker)))],
        } for session in ordered)

    identity = {
        **({"median5_profile": "wealth-core-median5-v1",
            "median5_spy_sha256": _stream_sha256(
                (session, _exact_price_ratio(value, window.median5_spy_closes[ordered[0]]))
                for session, value in sorted(window.median5_spy_closes.items())),
            "median5_terminal_sha256": _stream_sha256(
                (s, sorted(ids)) for s, ids in sorted(window.median5_terminals.items()))}
           if hasattr(window, "median5_spy_closes") else {}),
        "schema": ('sentinel.shadow-window-warmup-input/1' if expected_sessions == 299 else WARMUP_INPUT_SCHEMA),
        "first_warmup_session": ordered[0],
        "last_warmup_session": ordered[-1],
        "session_count": len(ordered),
        "sessions_sha256": _canonical_sha256(ordered),
        "bars_sha256": _stream_sha256(bar_rows()),
        "metadata_mode": metadata_mode,
        "metadata_sha256": _stream_sha256(metadata_values),
    }
    identity["warmup_input_sha256"] = _canonical_sha256(identity)
    return json.loads(_canonical_json(identity))
